def base_order(security, amount, limit_price=None, priceGear=None):
    asset = assure_asset(security)
    if limit_price == 'None' or limit_price is not None:
        amount = int(amount)
        limit_price = float(limit_price)
        style = LimitOrder(limit_price)
    elif priceGear is not None:
        style = GearOrder(priceGear)
    else:
        style = MarketOrder()
    if amount > 0:
        entrust_direction = EntrustDirection.BUY
    elif amount < 0:
        entrust_direction = EntrustDirection.SELL
        amount = -amount
        if security.replace('XSHG', 'SS').replace('XSHE', 'SZ') not in ('131810.SZ', '131811.SZ', '131800.SZ', '131809.SZ', '131801.SZ', '204001.SS', '204002.SS', '204003.SS', '204004.SS', '204007.SS') and Engine.instance().config.strategy.run_type != RunType.TRADING:
            position = engine_instance().get_positions(security)
            if position.sellable == 0:
                strategy_log.warning('股票可卖持仓数量为0, 无法卖出, 委托取消')
                return None
            elif position.sellable < amount:
                strategy_log.warning('委托卖出数量{1}, 股票实际可卖出持仓数量为{0}, 调整卖出量为{0}'.format(position.sellable, amount))
                amount = position.sellable
        order_obj = iq_order(asset_or_symbol=asset, amount=amount, entrust_direction=entrust_direction, style=style, futures_direction=FuturesDirection.OPEN, hedge_type=HedgeType.SPECULATION)
        if order_obj is None:
            return None
        elif is_trade() or asset.symbol[:2] in ('11', '12'):
            info = '生成订单，订单号:{order_id}，可转债代码：{symbol}，数量：{side}{share}'
        else:
            info = '生成订单，订单号:{order_id}，股票代码：{symbol}，数量：{side}{share}股'
        strategy_log.info(info.format(order_id=order_obj.order_id, symbol=order_obj.symbol, side='买入' if order_obj.entrust_direction.value.upper() == 'BUY' else '卖出', share=order_obj.amount))
        return order_obj.order_id
    else:
        strategy_log.warning('股票委托数量为0, 委托取消')
