def sell_close(contract, amount, limit_price=None, close_today=False):
    asset = assure_asset(contract)
    if asset.type != AssetType.FUTURE.value:
        strategy_log.warning('%s非期货标的, 委托取消' % contract)
        return None
    elif asset.exchange == 'XSGE':
        if close_today:
            futures_direction = FuturesDirection.CLOSE_TODAY
            current_amount = engine_instance().get_positions(asset.symbol).buy_today_amount
            if current_amount == 0:
                strategy_log.warning('今仓持仓数量为0, 无法平仓, 委托取消')
        else:
            futures_direction = FuturesDirection.CLOSE
            current_amount = engine_instance().get_positions(asset.symbol).buy_amount
        if current_amount == 0:
            strategy_log.warning('持仓数量为0, 无法平仓, 委托取消')
            return None
        elif current_amount < amount:
            strategy_log.warning('持仓数量为{0}, 无法平仓{1}, 调整平仓量为{0}'.format(current_amount, amount))
            amount = current_amount
        return future_order(asset, amount, EntrustDirection.SELL, futures_direction, limit_price=limit_price)
    elif close_today:
        strategy_log.warning(_('当前交易所合约【{}】不支持平今仓方式, 改用CLOSE方式进行平仓交易').format(contract))
