def get_split_orders(symbol_or_asset=None):
    if symbol_or_asset is None:
        return OrderSplitStore().store
    else:
        asset = assure_asset(symbol_or_asset)
        return [split_order for split_order in OrderSplitStore().store if asset == split_order.asset]
