@ExecutionContext.enforce_phase(ExecutionPhase.ON_HANDLE_DATA, ExecutionPhase.ON_ORDER_RSP, ExecutionPhase.ON_TRADE_RSP, ExecutionPhase.ON_HANDLE_TICK, ExecutionPhase.SCHEDULED, ExecutionPhase.GLOBAL, ExecutionPhase.BEFORE_TRADING_START, ExecutionPhase.AFTER_TRADING_END)
@arg_checker.apply_rules(arg_checker.verify_arg('contract').is_instance(six.string_types), arg_checker.verify_arg('amount').is_instance(int), arg_checker.verify_arg('limit_price').is_instance((float, int, None.__class__)))
def option_sell_close(contract, amount, limit_price=None):
    asset = assure_asset(contract)
    if asset.type != AssetType.OPTION.value:
        strategy_log.warning('%s非期权标的, 委托取消' % contract)
        return None
    else:
        futures_direction = FuturesDirection.CLOSE
        current_amount = engine_instance().get_positions(asset.symbol).buy_amount
        if current_amount == 0:
            strategy_log.warning('持仓数量为0, 无法平仓, 委托取消')
            return None
        elif current_amount < amount:
            strategy_log.warning('持仓数量为{0}, 无法平仓{1}, 调整平仓量为{0}'.format(current_amount, amount))
            amount = current_amount
        return option_order(asset, amount, EntrustDirection.SELL, futures_direction, limit_price=limit_price)
